}

func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		if m.detailPage != nil {
			switch msg.Type {
			case tea.KeyEsc:
				return m, func() tea.Msg { return closeDetailMsg{} }
			case tea.KeyCtrlC:
				return m, tea.Quit
			}
			return m, nil
		}

		switch msg.Type {
		case tea.KeyEnter:
			if row := m.selectedRow(); row != nil {
				selected := *row
				return m, func() tea.Msg { return openDetailMsg{row: selected} }
			}
		case tea.KeyCtrlC:
			return m, tea.Quit
		}

	case openDetailMsg:
		m.detailPage = newDetailModel(m.styles, msg.row)
		return m, nil

	case closeDetailMsg:
		m.detailPage = nil
		return m, nil
	}

	var cmd tea.Cmd
	m.table, cmd = m.table.Update(msg)
	return m, cmd
}

func (m rootModel) View() string {
	if m.detailPage != nil {
		return m.detailPage.view()
